/* Review workflow prototype. References only: no identity documents or credentials are uploaded. */
const BROKER_CHECKS=[['registry','Улсын бүртгэл','Албан бүртгэл дэх нэр, дугаар, идэвхтэй төлөвийг тулгасан.'],['license','Зуучлалын зөвшөөрөл','Зөвшөөрлийн эзэмшигч, дугаар, хүчинтэй хугацааг албан эх сурвалжаар шалгасан.'],['authority','Төлөөлөх эрх','Төлөөлөгч тухайн байгууллагыг төлөөлөх эрхтэйг баримтаар шалгасан.'],['identity','Эрх бүхий хүний таних шалгалт','Хамгаалалттай шалгалтын лавлагааг нягталсан. Иргэний үнэмлэхний хуулбар энд хадгалахгүй.'],['office','Бодит ажлын байр','Оффисын хаяг, байгууллагын байршлын нотолгоог тулгасан.'],['contact','Бие даасан холбоо барих шалгалт','Албан эх сурвалжаас авсан дугаарт холбогдож, эрх бүхий хүнийг баталсан.']];
const BROKER_OFFICE_KEYS=['name','registration','agent','phone','email','address','licenseNumber','licenseValidUntil'];
const BROKER_REFS=[['registryRef','Улсын бүртгэлийн материалын лавлагаа'],['licenseRef','Зөвшөөрлийн материалын лавлагаа'],['authorityRef','Төлөөлөх эрхийн материалын лавлагаа'],['officeRef','Оффисын нотолгооны лавлагаа']];
Object.assign(ADMIN_LABELS,{not_submitted:'Хүсэлт ирээгүй',submitted:'Хүсэлт ирсэн',changes_requested:'Нэмэлт материал',first_review:'1-р шат дууссан',needs_review:'Дахин хяналт шаардлагатай'});
function brokerApplication(){const p=proState();if(!p.brokerApplication||typeof p.brokerApplication!=='object')p.brokerApplication={status:'draft',revision:0,refs:{}};return p.brokerApplication}
function brokerNormalize(value){return String(value||'').normalize('NFKC').trim().replace(/\s+/g,' ').toLowerCase()}
function brokerKey(office=proState().office,refs=brokerApplication().refs||{},revision=brokerApplication().revision||0){return JSON.stringify([...BROKER_OFFICE_KEYS.map(k=>[k,brokerNormalize(office[k])]),...BROKER_REFS.map(([k])=>[k,brokerNormalize(refs[k])]),['revision',revision]])}
function brokerPlusDays(date,days){const value=new Date(date+'T12:00:00Z');value.setUTCDate(value.getUTCDate()+days);return value.toISOString().slice(0,10)}
function brokerValidDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return false;const d=new Date(value+'T12:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===value}
function brokerProfileErrors(p=proState().office,refs=brokerApplication().refs||{}){const errors=[];for(const [key,title] of [['name','Байгууллагын нэр'],['registration','Улсын бүртгэлийн дугаар'],['agent','Эрх бүхий төлөөлөгч'],['address','Оффисын хаяг'],['licenseNumber','Зөвшөөрлийн дугаар']])if(String(p[key]||'').trim().length<2)errors.push(title+' оруулна уу.');if(!/^(?:\+?976)?\d{8}$/.test(String(p.phone||'').replace(/[\s()-]/g,'')))errors.push('Монгол холбоо барих дугаараа оруулна уу.');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.email||''))errors.push('Байгууллагын имэйл оруулна уу.');if(!brokerValidDate(p.licenseValidUntil)||p.licenseValidUntil<proToday())errors.push('Зөвшөөрлийн хүчинтэй хугацааг шалгана уу.');for(const [key,label] of BROKER_REFS)if(String(refs[key]||'').trim().length<3)errors.push(label+' оруулна уу.');return errors}
function brokerSubmitted(){const a=brokerApplication();return a.status==='submitted'&&a.key===brokerKey()&&!brokerProfileErrors().length}
function brokerFirstValid(review=adminState().brokerReviews['broker-local'],fresh=true){if(!review?.first||!brokerSubmitted()||review.key!==brokerKey()||review.first.key!==review.key)return false;const first=review.first;return !!first.reviewer&&BROKER_CHECKS.every(([k])=>first.checks?.[k]&&String(first.refs?.[k]||'').trim().length>=3)&&brokerValidDate(first.checkedOn)&&first.checkedOn<=proToday()&&(!fresh||first.checkedOn>=brokerPlusDays(proToday(),-30))&&brokerValidDate(first.validUntil)&&first.validUntil>=proToday()&&first.validUntil<=proState().office.licenseValidUntil}
function brokerStatus(id='broker-local'){if(id!=='broker-local')return 'pending';const r=adminState().brokerReviews[id],a=brokerApplication();if(r?.status==='suspended')return 'suspended';if(r?.status==='approved'){if(brokerSubmitted()&&r.key!==a.key)return 'submitted';if(r.workflowVersion!==2||!r.first||!r.final)return 'needs_review';if(!brokerValidDate(r.final.validUntil)||r.final.validUntil<proToday()||proState().office.licenseValidUntil<proToday())return 'expired';if(!brokerSubmitted()||r.key!==brokerKey())return 'needs_review';if(!brokerFirstValid(r,false)||!r.final.reviewer||brokerNormalize(r.final.reviewer)===brokerNormalize(r.first.reviewer)||!r.final.independent||!r.final.confirmed||r.final.validUntil>r.first.validUntil)return 'needs_review';return 'approved'}if(r&&['rejected','changes_requested'].includes(r.status)&&(!brokerSubmitted()||r.key===a.key))return r.status;if(!brokerSubmitted())return a.status==='draft'?'not_submitted':'needs_review';if(r?.key===a.key&&['rejected','changes_requested'].includes(r.status))return r.status;if(r?.status==='first_review'&&brokerFirstValid(r))return 'first_review';return 'submitted'}
function brokerEligible(id='broker-local'){return brokerStatus(id)==='approved'}
function brokerVerificationBadge(id='broker-local',compact=false){if(!brokerEligible(id))return '';const until=adminState().brokerReviews[id]?.final?.validUntil||'';return brokerBadgeMarkup({id,compact,title:'ӨРӨӨ платформын хоёр шатны хяналт · Демо'+(until?' · Хүчинтэй: '+until:'')})}
function brokerBadgeMarkup({id='',compact=false,preview=false,title=''}){return `<span class="broker-verified-badge${compact?' is-compact':''}${preview?' is-preview':''}" ${preview?'data-broker-badge-preview="true"':'data-broker-badge="'+esc(id)+'"'} role="img" aria-label="${esc(preview?'Баталгаажсан зуучлагч · Тэмдгийн загвар':'ӨРӨӨ платформоор баталгаажсан зуучлагч · Демо')}" title="${esc(title)}">${icon('badge-check')}<span>Баталгаажсан зуучлагч</span><small>${preview?'Загвар':'Демо'}</small></span>`}
function brokerListingBadge(h){const id=officeIdentity(h)?.officeId;const badge=id?brokerVerificationBadge(id,true):'';return badge?'<div class="broker-card-verification">'+badge+'</div>':''}
function brokerBadgeGuide(){return `<section class="broker-badge-guide"><div><b>${icon('badge-check')}Баталгаажсан зуучлагчийн тэмдэг</b><button type="button" onclick="brokerShowBadgeInfo()">Тэмдгийн загвар ${icon('chevron-right')}</button></div><p>Хоёр шатны хүчинтэй шийдвэртэй байгууллагад автоматаар харагдана. Хугацаа дуусах, түр зогсоох эсвэл үндсэн мэдээлэл өөрчлөгдөхөд тэмдэг арилна.</p></section>`}
function brokerShowBadgeInfo(){modal(`<div class="broker-badge-preview"><span class="broker-badge-eyebrow">ТЭМДГИЙН ЗАГВАР · ӨРӨӨ</span><h2>Баталгаажсан зуучлагч</h2><p>Баталсан үед харагдах загвар</p><div class="broker-badge-sample">${brokerBadgeMarkup({preview:true,title:'Зөвхөн тэмдгийн загвар · Байгууллага баталсан шийдвэр биш'})}</div><ul><li>Байгууллагын хоёр шатны хяналт хүчинтэй үед л бодит профайл, зар дээр харагдана.</li><li>Хугацаа дуусах, түр зогсоох, үндсэн мэдээлэл өөрчлөгдөхөд автоматаар арилна.</li><li>DAN баталгаажуулалт, төрийн зөвшөөрөл эсвэл тухайн зарын үнэн зөвийн баталгаа биш.</li></ul><p class="broker-badge-demo-note">Энэ бол харагдацын жишээ. Одоогийн байгууллагын шийдвэрийг өөрчлөхгүй. Бодит DAN холболт болон серверийн баталгаажуулалт хийгдээгүй.</p><button type="button" class="primary" onclick="closeOverlay()">Ойлголоо</button></div>`);document.querySelector('.modal').classList.add('broker-badge-modal')}
function brokerRefreshBadges(){for(const badge of document.querySelectorAll('[data-broker-badge]'))if(!brokerEligible(badge.getAttribute('data-broker-badge')))badge.remove()}
function brokerBadgeWatch(){brokerRefreshBadges();setTimeout(brokerBadgeWatch,60000)}
setTimeout(brokerBadgeWatch,60000);
window.addEventListener('focus',brokerRefreshBadges);
document.addEventListener('visibilitychange',brokerRefreshBadges);
function brokerText(status=brokerStatus()){return {not_submitted:'Байгууллагын мэдээлэл, материалын лавлагаагаа бүрдүүлж хүсэлт илгээнэ үү.',submitted:'Материалын 1-р шатны хяналт хүлээгдэж байна.',first_review:'1-р шат дууссан. Өөр хянагчийн эцсийн шийдвэр хүлээгдэж байна.',needs_review:'Өмнөх шийдвэрийн материал эсвэл байгууллагын мэдээлэл өөрчлөгдсөн. Дахин хянана.',expired:'Баталгаажуулалтын хугацаа дууссан. Дахин хүсэлт илгээнэ үү.',changes_requested:'Админы шаардсан нэмэлт мэдээллийг бүрдүүлж дахин илгээнэ үү.',rejected:'Хүсэлтэд татгалзсан. Шалтгааныг нягталж шинэчилсэн мэдээллээр дахин илгээнэ үү.',suspended:'Байгууллагыг админ түр зогсоосон. Мэдээлэл засах нь энэ шийдвэрийг цуцлахгүй.',approved:'Хоёр шатны хяналтын демо бүртгэл хүчинтэй. Зар бүр тусдаа хяналтад орно.'}[status]||'Баталгаажуулалт шаардлагатай.'}
function brokerProBanner(){const s=brokerStatus(),r=adminState().brokerReviews['broker-local'];return `<div class="broker-pro-banner ${s==='approved'?'is-ready':''}">${icon('shield')}<div><b>Байгууллагын баталгаажуулалт · ${esc(ADMIN_LABELS[s])}</b><p>${esc(brokerText(s))}${s!=='approved'?' Хяналт дуусаагүй үед зар болон сурталчилгаа нийтэд харагдахгүй.':''}</p>${r?.reason?'<p>'+esc(r.reason)+'</p>':''}</div><a href="#/pro/settings">Материал / Төлөв ${icon('chevron-right')}</a></div>`}
function brokerInput(label,name,value='',type='text',required=true){return `<label class="broker-field"><span>${label}</span><input name="${name}" aria-label="${esc(label)}" type="${type}" value="${esc(value)}" ${required?'required':''} maxlength="180"></label>`}
function brokerSources(){return `<div class="broker-sources"><a href="https://e-business.mn/en/home" target="_blank" rel="noopener noreferrer">${icon('external-link')}e-Business · Улсын бүртгэл</a><a href="https://license.frc.mn/" target="_blank" rel="noopener noreferrer">${icon('external-link')}СЗХ · Зөвшөөрлийн систем</a><p>Админ эх сурвалжийг өөрөө шалгаж тэмдэглэнэ. Автомат лавлагаа, таних болон утасны баталгаажуулалт холбогдоогүй.</p></div>`}
function brokerProPanel(){const a=brokerApplication(),r=adminState().brokerReviews['broker-local'],s=brokerStatus();return `<section class="pro-panel broker-application"><div class="pro-panel-head"><div><h2>Байгууллагын баталгаажуулалтын хүсэлт</h2><p>Мэдээлэл → 1-р хяналт → 2-р хяналт → Хугацаатай шийдвэр</p></div>${adminBadge(s)}</div><p class="pro-note">Дээд талын байгууллагын мэдээллээ эхлээд хадгална. Энд зөвхөн материалын лавлагааны дугаарыг бичнэ. Эх баримт, иргэний үнэмлэх, хувийн регистр болон банкны мэдээлэл бүү оруулаарай. Хамгаалалттай файл хадгалах сервер хараахан холбогдоогүй.</p><form onsubmit="brokerSubmitApplication(event)"><div class="broker-fields">${BROKER_REFS.map(([key,label])=>brokerInput(label,key,a.refs?.[key]||'')).join('')}</div><label class="broker-consent"><input name="confirm" type="checkbox" required>Демо материалын лавлагаа болон хадгалсан байгууллагын мэдээллээ шалгасан.</label><p class="broker-form-error" role="alert"></p><div class="broker-form-actions"><button class="primary">${icon('shield')}${a.revision?'Шинэчилж хяналтад илгээх':'Хяналтад илгээх'}</button></div></form><div class="broker-application-status"><p>Хүсэлтийн хувилбар: <b>${a.revision||0}</b>${a.submittedAt?' · '+esc(a.submittedAt.slice(0,10)):''}</p><p>${esc(brokerText(s))}</p>${r?.reason?'<p><b>Админы тайлбар</b><br>'+esc(r.reason)+'</p>':''}${r?.final&&s==='approved'?'<p>Демо шийдвэр хүчинтэй: '+esc(r.final.validUntil)+'</p>':''}</div></section>${brokerBadgeGuide()}`}
function brokerSubmitApplication(event){event.preventDefault();const f=new FormData(event.target),refs=Object.fromEntries(BROKER_REFS.map(([key])=>[key,String(f.get(key)||'').trim()])),errors=brokerProfileErrors(proState().office,refs);if(!f.has('confirm'))errors.push('Мэдээллээ шалгаснаа тэмдэглэнэ үү.');if(errors.length)return brokerError(event,errors.join(' '));const current=brokerApplication(),key=brokerKey(proState().office,refs);if(current.status==='submitted'&&current.key===key&&!['expired','rejected','changes_requested','needs_review'].includes(brokerStatus()))return brokerError(event,'Ижил хувилбар аль хэдийн хяналтад байна.');adminCommit('Байгууллагын хүсэлт',proState().office.name,()=>{proState().brokerApplication={status:'submitted',revision:Number(current.revision||0)+1,refs,key:brokerKey(proState().office,refs,Number(current.revision||0)+1),submittedAt:new Date().toISOString()}},current.status,'submitted','Хүсэлтийн шинэ хувилбар','Өрөө PRO · Демо хүсэлт')}
function brokerAdminPage(){const p=proState().office,r=adminState().brokerReviews['broker-local']||{},a=brokerApplication(),s=brokerStatus(),complete=BROKER_OFFICE_KEYS.filter(k=>String(p[k]||'').trim()).length;return `${adminHeading('БАЙГУУЛЛАГА БА ЗУУЧЛАГЧ','Зуучлагчийн баталгаажуулалт','Материалын нотолгоо, хоёр өөр хянагч, хугацаатай шийдвэр. Батлаагүй байгууллагын зар нийтэд гарахгүй.')}<div class="broker-assurance"><i>${icon('shield')}</i><div><b>Баталгаажаагүй бол нийтлэх эрх нээгдэхгүй.</b><p>Хоёр шатны хяналт, хувилбарын тохирол болон хүчинтэй хугацааг хамтад нь шалгана.</p></div><span>${adminBadge(s)}</span></div><div class="admin-panel admin-broker-card"><div class="admin-broker-logo">${icon('briefcase')}</div><div><span class="admin-eyebrow">ӨРӨӨ PRO · БАЙГУУЛЛАГЫН ХҮСЭЛТ</span><h2>${esc(p.name||'Нэр оруулаагүй')}</h2>${brokerVerificationBadge()}<p>${esc(p.agent||'Эрх бүхий төлөөлөгч оруулаагүй')} · ${esc(p.phone||'Утас оруулаагүй')}</p><p>${esc(p.address||'Оффисын хаяг оруулаагүй')}</p><p>Улсын бүртгэл: ${esc(p.registration||'Оруулаагүй')} · Зөвшөөрөл: ${esc(p.licenseNumber||'Оруулаагүй')}</p>${adminBadge(s)}<p class="admin-note">${esc(brokerText(s))}</p>${r.reason?'<p class="broker-decision-reason">'+esc(r.reason)+'</p>':''}</div><div class="admin-broker-stats"><strong>${homes.filter(h=>adminBrokerId(h)==='broker-local').length}</strong><span>холбоотой зар</span><button class="admin-primary" onclick="brokerOpenReview()">${icon('shield')}Материал шалгах</button><a href="#/pro/settings">PRO хүсэлтийг харах ${icon('arrow-up-right')}</a></div></div><div class="broker-stage-grid">${[['1','Бүрдүүлэлт',complete+' / '+BROKER_OFFICE_KEYS.length+' мэдээлэл · '+(a.revision||0)+' хүсэлт'],['2','Нотолгооны хяналт',r.first&&brokerFirstValid(r)?'1-р шатны бүртгэл байна':'6 шалгалт, эх сурвалжийн лавлагаа'],['3','Давхар хяналт',s==='approved'?'2-р шатны бүртгэл хүчинтэй':'Өөр хянагчийн шийдвэр'],['4','Хугацаа ба өөрчлөлт',r.final?.validUntil?'Хүчинтэй: '+r.final.validUntil:'90 хүртэл хоног · Дахин хяналт']].map(([n,title,copy])=>`<section class="admin-panel"><i>${n}</i><h3>${title}</h3><p>${esc(copy)}</p></section>`).join('')}</div><div class="broker-review-grid"><section class="admin-panel"><div class="admin-panel-head"><h2>Заавал нягтлах 6 зүйл</h2><span>Гар хяналт</span></div>${BROKER_CHECKS.map(([key,title,copy])=>`<div class="broker-check-summary"><i>${r.first?.checks?.[key]?icon('check'):icon('clock')}</i><div><b>${title}</b><p>${copy}</p></div></div>`).join('')}</section><section class="admin-panel"><div class="admin-panel-head"><h2>Шийдвэрийн нөхцөл</h2></div><ul class="broker-policy-list"><li>Хүсэлт, албан эх сурвалжийн шалгалтын лавлагаагүй бол батлахгүй.</li><li>Эхний ба эцсийн хянагчийн код ялгаатай байна.</li><li>Эцсийн хугацаа нь зөвшөөрлийн хугацаа болон 90 хоногоос хэтрэхгүй.</li><li>Нэр, бүртгэл, зөвшөөрөл, төлөөлөгч, утас, хаяг өөрчлөгдвөл дахин хянана.</li><li>Хугацаа дуусах, түр зогсоох үед зар ба сурталчилгаа автоматаар харагдахгүй.</li><li>Баталгаажсан байгууллагын зар бүр тусдаа админ хяналтад орно.</li></ul>${brokerSources()}<p class="admin-note">90 хоног нь платформын дотоод хяналтын бодлого. Энэ демо нь хууль ёсны эрх, эх баримтын жинхэнэ эсэхийг баталсан баталгаа биш.</p></section></div>${brokerBadgeGuide()}${brokerReviewHistory()}`}
function brokerOpenReview(){const p=proState().office,a=brokerApplication(),r=adminState().brokerReviews['broker-local']||{},s=brokerStatus(),ready=brokerSubmitted(),second=r.status==='first_review'&&brokerFirstValid(r),expires=[p.licenseValidUntil,brokerPlusDays(proToday(),90)].filter(Boolean).sort()[0]||'';modal(`<div class="admin-modal-heading"><span>БАЙГУУЛЛАГЫН ХЯНАЛТ · ДЕМО</span><h2>${esc(p.name)}</h2><p>${esc(brokerText(s))}</p></div><div class="broker-review-snapshot"><p>Бүртгэл: <b>${esc(p.registration||'—')}</b> · Зөвшөөрөл: <b>${esc(p.licenseNumber||'—')}</b></p><p>${esc(p.agent||'—')} · ${esc(p.phone||'—')} · ${esc(p.email||'—')}</p><p>${esc(p.address||'—')} · Зөвшөөрөл хүчинтэй: ${esc(p.licenseValidUntil||'—')}</p><p>Хүсэлтийн хувилбар: ${a.revision||0}</p>${BROKER_REFS.map(([key,label])=>`<p>${label}: <b>${esc(a.refs?.[key]||'Оруулаагүй')}</b></p>`).join('')}</div>${brokerSources()}${ready?`<form class="broker-review-form" onsubmit="${second?'brokerSubmitFinal':'brokerSubmitFirst'}(event)"><input type="hidden" name="key" value="${esc(a.key)}"><h3>${second?'2-р шат · Эцсийн хяналт':'1-р шат · Материалын хяналт'}</h3>${second?`<div class="broker-first-record"><b>1-р хянагч: ${esc(r.first.reviewer)}</b><p>${esc(r.first.checkedOn)} · ${esc(r.first.note)}</p>${BROKER_CHECKS.map(([key,title])=>`<p>${title}: ${esc(r.first.refs[key])}</p>`).join('')}</div><label class="broker-review-check"><input type="checkbox" name="independent" required>Албан эх сурвалж, материалын лавлагааг бие даан дахин нягталсан.</label><label class="broker-review-check"><input type="checkbox" name="confirmed" required>Эхний хяналтын дүгнэлт, зургаан нотолгоог давхар шалгасан.</label>`:BROKER_CHECKS.map(([key,title,copy])=>`<div class="broker-check-row"><label class="broker-review-check"><input type="checkbox" name="check-${key}" required><span><b>${title}</b><small>${copy}</small></span></label>${brokerInput('Шалгасан эх сурвалж / кейсийн лавлагаа · '+title,'ref-'+key,'')}</div>`).join('')}${brokerInput(second?'Эцсийн хянагчийн код (демо)':'1-р хянагчийн код (демо)','reviewer','')}${!second?brokerInput('Эх сурвалж шалгасан огноо','checkedOn',proToday(),'date'):''}${brokerInput('Шийдвэр хүчинтэй хүртэл','validUntil',second?r.first.validUntil:expires,'date')}${adminTextarea('Хяналтын дүгнэлт','note','')}<p class="broker-form-note">Хянагчийн код нь энэ демод гараар бичигдэнэ. Бодит хоёр өөр ажилтан гэдгийг серверийн эрх, нэвтрэлтээр баталгаажуулах шаардлагатай. Хувийн регистр, үнэмлэхний хуулбар энд бүү бичнэ үү.</p><p class="broker-form-error" role="alert"></p><div class="broker-form-actions"><button type="button" onclick="closeOverlay()">Буцах</button><button class="admin-primary">${icon('shield')}${second?'Эцсийн хяналтаар батлах':'1-р шатыг хадгалах'}</button></div></form>`:`<div class="broker-blocked"><b>${s==='approved'?'Хоёр шатны шийдвэр байна':'Одоогоор батлах боломжгүй'}</b><p>${!ready?'Хүчинтэй, бүрэн хүсэлт PRO-оос ирээгүй. Мэдээлэл бүрдүүлж дахин илгээнэ үү.':'Шинэ хяналт шаардлагатай.'}</p><a href="#/pro/settings" onclick="closeOverlay()">PRO хүсэлт рүү очих ${icon('arrow-up-right')}</a></div>`}<details class="broker-adverse"><summary>Нэмэлт материал / Татгалзах / Түр зогсоох</summary><form onsubmit="brokerSubmitDecision(event)">${adminSelect('Байгууллагын шийдвэр','status',['changes_requested','rejected','suspended','pending'],'changes_requested')}${brokerInput('Шийдвэр гаргасан хянагчийн код (демо)','reviewer','')}${adminTextarea('Шийдвэрийн шалтгаан','reason',r.reason||'')}<p class="broker-form-error" role="alert"></p><div class="broker-form-actions"><button class="admin-primary">Шийдвэр хадгалах</button></div></form></details>`);document.querySelector('.modal').classList.add('admin-modal','broker-review-modal')}
function brokerFormValues(event){const f=new FormData(event.target);return {f,key:String(f.get('key')||''),reviewer:String(f.get('reviewer')||'').trim(),validUntil:String(f.get('validUntil')||''),note:String(f.get('note')||'').trim()}}
function brokerCommonError(v){if(!brokerSubmitted()||v.key!==brokerKey())return 'Хүсэлтийн мэдээлэл өөрчлөгдсөн. Шинэ хувилбарыг нээнэ үү.';if(brokerStatus()==='suspended')return 'Түр зогсоосон байгууллагыг эхлээд дахин хяналтад шилжүүлнэ үү.';if(v.reviewer.length<2||v.note.length<5)return 'Хянагчийн код, дэлгэрэнгүй дүгнэлтээ бичнэ үү.';if(!brokerValidDate(v.validUntil)||v.validUntil<proToday()||v.validUntil>brokerPlusDays(proToday(),90)||v.validUntil>proState().office.licenseValidUntil)return 'Хүчинтэй хугацаа нь өнөөдрөөс хойш, зөвшөөрөл болон 90 хоногийн хязгаарт багтана.';return ''}
function brokerSubmitFirst(event){event.preventDefault();const v=brokerFormValues(event),error=brokerCommonError(v),checkedOn=String(v.f.get('checkedOn')||''),checks=Object.fromEntries(BROKER_CHECKS.map(([k])=>[k,v.f.has('check-'+k)])),refs=Object.fromEntries(BROKER_CHECKS.map(([k])=>[k,String(v.f.get('ref-'+k)||'').trim()]));if(error)return brokerError(event,error);if(!BROKER_CHECKS.every(([k])=>checks[k]&&refs[k].length>=3))return brokerError(event,'Зургаан шалгалт, тус бүрийн нотолгооны лавлагааг бүрдүүлнэ үү.');if(!brokerValidDate(checkedOn)||checkedOn>proToday()||checkedOn<brokerPlusDays(proToday(),-30))return brokerError(event,'Шалгасан огноо ирээдүйд эсвэл 30 хоногоос хуучин байж болохгүй.');const previous=brokerStatus();adminCommit('Зуучлагч · 1-р шат',proState().office.name,()=>{brokerArchiveReview();adminState().brokerReviews['broker-local']={workflowVersion:2,key:v.key,status:'first_review',reason:v.note,date:new Date().toISOString(),first:{key:v.key,reviewer:v.reviewer,checkedOn,validUntil:v.validUntil,note:v.note,checks,refs,date:new Date().toISOString()}}},previous,'first_review',v.reviewer+' · '+v.note)}
function brokerSubmitFinal(event){event.preventDefault();const v=brokerFormValues(event),r=adminState().brokerReviews['broker-local'],error=brokerCommonError(v);if(error)return brokerError(event,error);if(r?.status!=='first_review'||!brokerFirstValid(r))return brokerError(event,'Хүчинтэй 1-р шатны хяналт эхлээд шаардлагатай.');if(brokerNormalize(v.reviewer)===brokerNormalize(r.first.reviewer))return brokerError(event,'Эхний хянагчаас өөр кодтой эцсийн хянагч шаардлагатай.');if(!v.f.has('independent')||!v.f.has('confirmed'))return brokerError(event,'Бие даасан давхар хяналтаа тэмдэглэнэ үү.');if(v.validUntil>r.first.validUntil)return brokerError(event,'Эхний хяналтын хүчинтэй хугацааг сунгаж болохгүй.');adminCommit('Зуучлагч · Эцсийн хяналт',proState().office.name,()=>{brokerArchiveReview();r.status='approved';r.reason=v.note;r.final={reviewer:v.reviewer,independent:true,confirmed:true,note:v.note,validUntil:v.validUntil,date:new Date().toISOString()};r.date=new Date().toISOString()},'first_review','approved',v.reviewer+' · '+v.note)}
function brokerSubmitDecision(event){event.preventDefault();const f=new FormData(event.target),status=String(f.get('status')),reviewer=String(f.get('reviewer')||'').trim(),reason=String(f.get('reason')||'').trim();if(!['changes_requested','rejected','suspended','pending'].includes(status))return brokerError(event,'Шууд батлах үйлдэл байхгүй. Хоёр шатны хяналтыг гүйцээнэ үү.');if(reviewer.length<2||reason.length<5)return brokerError(event,'Хянагчийн код, шийдвэрийн шалтгааныг оруулна уу.');const before=brokerStatus();adminCommit('Зуучлагчийн шийдвэр',proState().office.name,()=>{brokerArchiveReview();adminState().brokerReviews['broker-local']={workflowVersion:2,status,key:brokerApplication().key||'',reason,date:new Date().toISOString(),reviewer}},before,status,reviewer+' · '+reason)}
function brokerError(event,text){const target=event.target.querySelector('.broker-form-error')||event.target.querySelector('.admin-form-error');if(target)target.textContent=text}

function brokerArchiveReview(){const r=adminState().brokerReviews['broker-local'];if(!r)return;adminState().brokerHistory.unshift({...JSON.parse(JSON.stringify(r)),archivedAt:new Date().toISOString()});adminState().brokerHistory=adminState().brokerHistory.slice(0,500)}
function brokerReviewHistory(){const rows=adminState().brokerHistory;return rows.length?`<section class="admin-panel broker-history"><div class="admin-panel-head"><h2>Өмнөх хяналтын бүртгэл</h2><span>Локал демо түүх</span></div>${rows.slice(0,10).map(r=>`<details><summary>${adminBadge(r.status)}<b>${esc(r.first?.reviewer||r.reviewer||'Өмнөх хувилбар')}${r.final?' → '+esc(r.final.reviewer):''}</b><span>${esc((r.date||r.archivedAt).slice(0,10))}</span></summary><p>${esc(r.reason||'Тайлбаргүй')}</p>${BROKER_CHECKS.filter(([k])=>r.first?.refs?.[k]).map(([k,title])=>'<p>'+title+': '+esc(r.first.refs[k])+'</p>').join('')}</details>`).join('')}</section>`:''}
